import './style.css';
import {createFloatingCapture} from './floating-capture.js';
import {parsePaymentText,captureFingerprint} from './capture.js';
import {uid,today,monthNow,cents,money,initialState,balance,totals,shiftMonth,nextDate,validDate,csv,validate,sortedCategories} from './model.js';
import {openStore,saveState,updateState,encodeBackup,decodeBackup} from './store.js';
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',chart:'M4 20V10m8 10V4m8 16v-7',wallet:'M3 6h16v14H3zM3 6V3h14v3m-3 7h7v4h-7z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'M12 4v16m-6-6 6 6 6-6',up:'M12 20V4m-6 6 6-6 6 6',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5m2-6a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-7-3 3 1 1-3h6l1 3 3-1 2 5-2 2 2 2-2 5-3-1-1 3H9l-1-3-3 1-2-5 2-2-2-2z',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',cloud:'M7 18a5 5 0 1 1 0-10 6 6 0 0 1 12 2 4 4 0 0 1 0 8M12 12v9m-3-6 3-3 3 3',repeat:'M4 8h14l-3-3m3 3-3 3M20 16H6l3 3m-3-3 3-3',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',check:'m5 12 4 4 10-10',edit:'m14 4 6 6M4 16 16 4l4 4L8 20H4z',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',tag:'M3 3h8l10 10-8 8L3 11zM7 7h.01',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',info:'M12 11v6m0-10h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};
const icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.tag}"/></svg>`;
const symbols={'餐饮':'🍜','购物':'🛍','交通':'🚇','居住':'🏠','娱乐':'🎮','健康':'💊','学习':'📚','人情':'🎁','其他':'🧾','工资':'💼','奖金':'✨','理财':'🌱','其他收入':'💰'};
Object.assign(symbols,{"饮料":"🥤","日用":"🧻","亲友":"🤝","游戏":"🕹️","蔬菜":"🥬","水果":"🍎","零食":"🍪","运动":"⚽","通讯":"📱","服饰":"👕","美容":"💄","住房":"🏠","健身":"🏋️","居家":"🛋️","孩子":"🧸","长辈":"🧓","社交":"🥂","旅行":"🧳","烟酒":"🍷","数码":"💻","汽车":"🚗","医疗":"🩺","书籍":"📖","宠物":"🐾","礼金":"🧧","礼物":"🎁","办公":"📎","维修":"🔧","捐赠":"❤️","彩票":"🎟️","快递":"📦","约会":"💐","兼职":"🛠️","其它":"💰"});
const palette=['#217363','#e6a269','#7995b5','#b3ac79','#b89cae','#8aa88e','#c58673','#91b7bc','#aaa99e'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const CAPTURE_MARKER='此剪切板记录为轻账专用';
let state,realState,tab='home',month=monthNow(),ledgerAll=false,demo=false,filter='all',query='',accountFilter='',reportPeriod='month',busy=false,modalContext=null,backupReady=null,importData=null,swWaiting=null,updateRequested=false,offlineRegistration=null,updateCheck=null,updateStatus='',reloadAvailable=false;
let channel;try{channel=new BroadcastChannel('qingzhang');channel.onmessage=async()=>{if(demo)return;state=await openStore();render();toast('账本已更新');};}catch{}
const cat=id=>state.categories.find(x=>x.id===id),account=id=>state.accounts.find(x=>x.id===id);
const monthTransactions=()=>state.transactions.filter(t=>t.date.startsWith(month));
const sortTx=ts=>ts.slice().sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));
const ledgerDayLabel=d=>{const [y,m,day]=d.split('-').map(Number);const weekday=['日','一','二','三','四','五','六'][new Date(Date.UTC(y,m-1,day)).getUTCDay()];return `${d===today()?'今天':`${m}月${day}日`}·星期${weekday}`;};
const labelMonth=()=>`${Number(month.slice(5))}月`;
const sumAccounts=()=>state.accounts.reduce((n,a)=>n+balance(state,a.id),0);
const btn=(action,text,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const floatingCapture=createFloatingCapture({app,onActivate:()=>{captureModal();void pasteCapture();}});
function updateFloatingCapture(){floatingCapture.update(!!state&&['home','ledger','reports','accounts'].includes(tab)&&!modalRoot.firstChild);}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3300);}
async function commit(fn){if(busy)return false;busy=true;try{if(demo){const s=structuredClone(state);const r=fn(s);state=validate(r||s);}else{state=await updateState(fn);channel?.postMessage('changed');}render();return true;}catch(e){toast(e.message||'保存失败，请先导出备份');return false;}finally{busy=false;}}
function openModal(title,html){modalRoot.innerHTML=`<div class="modal-shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-grab"></div><header class="sheet-header"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="sheet-body">${html}</div></section></div>`;document.body.classList.add('modal-open');app.inert=true;updateFloatingCapture();modalRoot.querySelector('.icon-button').focus();}
function closeModal(){app.inert=false;modalRoot.innerHTML='';document.body.classList.remove('modal-open');modalContext=null;importData=null;backupReady=null;updateFloatingCapture();}
function monthPicker(){const ledger=tab==='ledger',all=ledger&&ledgerAll,current=monthNow();return `<div class="month-picker"><button data-action="prev-month" aria-label="${all?'返回本月':'上个月'}" ${!all&&month<='1900-01'?'disabled':''}>${icon('left',16)}</button>${all?'<strong class="all-period">全部记录</strong>':`<label>${month.slice(0,4)}年 ${labelMonth()} ${icon('down',12)}<input aria-label="选择月份" id="month-input" type="month" value="${month}" min="1900-01" max="${ledger?current:'2200-12'}"></label>`}<button data-action="next-month" aria-label="${ledger&&(all||month>=current)?'全部记录':'下个月'}" ${all?'disabled':''}>${icon('chevron',16)}</button></div>`;}

function header(){return `<header class="topbar"><a class="brand" href="#" data-action="home"><span class="brand-mark">${icon('list',19)}</span>轻账<span class="brand-dot"></span></a><div class="top-actions"><span class="local-pill"><i></i>${demo?'演示账本':navigator.onLine?'本地已保存':'离线可用'}</span><button class="icon-button" data-action="settings" aria-label="设置与备份">${icon('settings')}</button></div></header>${demo?`<div class="demo-banner">正在体验示例数据，不影响你的账本 ${btn('exit-demo','退出','text-button')}</div>`:''}`;}
function nav(){return `<nav class="bottom-nav" aria-label="主要导航">${[['home','home','总览'],['ledger','list','明细'],['add','plus','记一笔'],['reports','chart','统计'],['accounts','wallet','账户']].map(([id,ic,label])=>`<button data-action="${id}" class="nav-item ${id===tab?'active':''} ${id==='add'?'nav-add':''}" ${id===tab?'aria-current="page"':''}><span>${icon(ic,id==='add'?25:22)}</span><small>${label}</small></button>`).join('')}</nav>`;}
function render(){if(!state)return;app.innerHTML=`${header()}<main>${({home:homeView,ledger:ledgerView,reports:reportsView,accounts:accountsView,settings:settingsView}[tab]||homeView)()}</main>${nav()}`;updateFloatingCapture();}
function txRow(t){const c=cat(t.categoryId),name=t.type==='transfer'?'账户转账':c?.name||'未分类';return `<button class="transaction" data-action="edit-tx" data-id="${esc(t.id)}"><span class="category-icon ${t.type}">${t.type==='transfer'?icon('repeat',20):symbols[name]||icon('tag',20)}</span><span class="tx-copy"><strong>${esc(t.note||name)}</strong><small>${esc(name)} <span>·</span> ${esc(account(t.accountId)?.name)}${t.type==='transfer'?' → '+esc(account(t.toAccountId)?.name):''}</small></span><span class="tx-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount)}<small>${t.date.slice(5).replace('-',' / ')}</small></span></button>`;}
function empty(title,desc,action='add',label='记下第一笔'){return `<div class="empty"><span class="empty-icon">${icon('list',30)}</span><h3>${title}</h3><p>${desc}</p>${action?btn(action,label,'primary small'):''}</div>`;}
function homeView(){const ts=monthTransactions(),t=totals(ts),budget=state.budgets[month]?.total||0,pct=budget?Math.min(100,t.expense/budget*100):0;const due=state.rules.filter(r=>r.next<=today());const last=state.settings.lastBackup;const backupOld=!last||(Date.now()-Date.parse(last)>7*864e5);return `<section class="page-heading"><div><p class="eyebrow">YOUR EVERYDAY, IN BALANCE</p><h1>生活有迹，心中有数<span class="orange-dot">.</span></h1><p class="subtle">把日子过好，从每一笔开始。</p></div><span class="sun-doodle">${icon('sun',35)}</span></section><div class="section-line">${monthPicker()}<span class="caption">${ts.length} 笔记录</span></div><section class="balance-card"><div class="balance-top"><span>本月支出</span><span class="card-badge">${icon('shield',13)} 私人账本</span></div><div class="hero-amount"><span>¥</span>${money(t.expense)}</div><div class="hero-footer"><div><span>本月收入 ${icon('down',12)}</span><strong>¥ ${money(t.income)}</strong></div><div><span>本月结余 ${icon('wallet',12)}</span><strong>¥ ${money(t.income-t.expense)}</strong></div></div><div class="hero-art" aria-hidden="true"><i></i><i></i><i></i></div></section><section class="budget-strip" data-action="budget" role="button" tabindex="0"><div class="section-line"><strong>${icon('wallet',17)} 月度预算</strong><span>${budget?`剩余 <b class="${t.expense>budget?'negative':''}">¥ ${money(budget-t.expense)}</b>`:'设置预算，让花销有计划'} ${icon('chevron',14)}</span></div><div class="progress"><i style="width:${pct}%;${pct>=100?'background:var(--orange)':''}"></i></div><div class="budget-meta"><span>${budget?`已使用 ${Math.round(t.expense/budget*100)}%`:'给这个月一个小目标'}</span><span>${budget?'预算 ¥ '+money(budget):'去设置'}</span></div></section><div class="quick-grid">${btn('add',`${icon('plus')}<span>记一笔</span><small>记录当下</small>`,'quick-button')}${btn('reports',`${icon('chart')}<span>看趋势</span><small>了解消费</small>`,'quick-button')}${btn('backup',`${icon('cloud')}<span>备份账本</span><small>安心留存</small>`,'quick-button')}</div>${due.length?`<button class="notice due" data-action="rules">${icon('repeat',19)}<span><strong>${due.length} 项周期账单待确认</strong><small>确认后计入账本，避免重复扣记</small></span>${icon('chevron',16)}</button>`:''}${btn('capture',icon('tag',18)+' 截图记账 · 粘贴快捷指令结果','wide-row')}<section class="card insight-card"><div class="insight-symbol">✦</div><div><span class="eyebrow">轻账小观察</span><p>${insight(ts)}</p></div></section><section class="transactions-section"><div class="section-line section-title"><h2>最近账单</h2>${btn('ledger','全部 '+icon('arrow',15),'text-button')}</div>${ts.length?`<div class="transaction-list">${sortTx(ts).slice(0,5).map(txRow).join('')}</div>`:empty('你的生活，值得记录','从一顿早餐、一杯咖啡开始。')} </section>${!state.transactions.length&&!demo?`<button class="demo-link" data-action="demo">先看看有账单时的样子 ${icon('arrow',15)}</button>`:''}${backupOld&&state.transactions.length?`<button class="notice" data-action="backup">${icon('shield',19)}<span><strong>${last?'该给账本备份了':'给你的账本加一份保障'}</strong><small>导出备份后，保存到 iCloud 云盘</small></span>${icon('chevron',16)}</button>`:''}<p class="privacy-footer">${icon('shield',12)} 数据只在你的设备中 · 没有广告，也没有追踪</p>`;}
function insight(ts){const t=totals(ts),expenses=ts.filter(t=>t.type==='expense');if(!expenses.length)return '记下第一笔支出，让轻账慢慢读懂你的生活。';const groups=groupCategories(expenses);const top=groups[0];const prev=totals(state.transactions.filter(x=>x.date.startsWith(shiftMonth(month,-1))));let s=`${esc(top.name)}占本月支出的 ${Math.round(top.amount/t.expense*100)}%，是你的主要开销。`;if(prev.expense){const n=Math.round((t.expense-prev.expense)/prev.expense*100);s+=`相比上月整月${n>=0?'增加':'减少'} ${Math.abs(n)}%。`;}else s+=`本月共记录 ${expenses.length} 笔支出，平均每笔 ¥${money(Math.round(t.expense/expenses.length))}。`;return s;}
function ledgerView(){let ts=(ledgerAll?state.transactions:monthTransactions()).filter(t=>(filter==='all'||t.type===filter)&&(!accountFilter||t.accountId===accountFilter||t.toAccountId===accountFilter)&&(!query||[t.note,cat(t.categoryId)?.name,account(t.accountId)?.name,(t.amount/100).toFixed(2)].join(' ').toLowerCase().includes(query.toLowerCase())));const t=totals(ts);const grouped=new Map();for(const t of sortTx(ts)){if(!grouped.has(t.date))grouped.set(t.date,[]);grouped.get(t.date).push(t);}const days=[...grouped.keys()];return `<div class="page-title"><div><p class="eyebrow">THE LITTLE THINGS ADD UP</p><h1>收支明细<span class="orange-dot">.</span></h1></div>${btn('export-csv',icon('download'),'icon-button','aria-label="导出 CSV"')}</div><div class="section-line">${monthPicker()}<span class="caption" id="ledger-count">${ts.length} 笔</span></div><div class="ledger-scope"><div class="segmented compact" aria-label="明细日期范围">${btn('ledger-current','本月',!ledgerAll&&month===monthNow()?'selected':'',`aria-pressed="${!ledgerAll&&month===monthNow()}"`)}${btn('ledger-all','全部',ledgerAll?'selected':'',`aria-pressed="${ledgerAll}"`)}</div><span class="caption">${ledgerAll?'搜索全部记录':'搜索所选月份'}</span></div><div class="search-field">${icon('search',19)}<input id="search" aria-label="搜索账单" placeholder="搜索备注、分类、金额" value="${esc(query)}" type="search" autocomplete="off"><button type="button" class="search-clear" data-action="clear-search" aria-label="清空搜索" ${query?'':'hidden'}>${icon('close',16)}</button></div><div class="filter-row"><div class="segmented">${[['all','全部'],['expense','支出'],['income','收入'],['transfer','转账']].map(([k,l])=>btn('filter',l,filter===k?'selected':'',`data-value="${k}"`)).join('')}</div><select id="account-filter" aria-label="筛选账户"><option value="">全部账户</option>${state.accounts.map(a=>`<option value="${esc(a.id)}" ${accountFilter===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div id="ledger-results"><div class="ledger-summary"><span>收入 <b class="positive">${money(t.income)}</b></span><span>支出 <b>${money(t.expense)}</b></span></div>${days.length?days.map(d=>{const list=grouped.get(d),n=totals(list);return `<section class="day-group"><div class="day-label"><strong>${ledgerAll?d.slice(0,4)+'年':''}${ledgerDayLabel(d)}</strong><span>支 ${money(n.expense)} · 收 ${money(n.income)}</span></div><div class="transaction-list">${list.map(txRow).join('')}</div></section>`;}).join(''):empty('没有找到记录','换个筛选条件，或为这一天添一笔。')}</div>`;}
function groupCategories(ts){const sums={};ts.forEach(t=>{if(t.type==='transfer')return;sums[t.categoryId]=(sums[t.categoryId]||0)+t.amount;});return Object.entries(sums).map(([id,amount])=>({id,amount,name:cat(id)?.name||'未分类'})).sort((a,b)=>b.amount-a.amount);}
function reportsView(){const ts=state.transactions.filter(t=>reportPeriod==='year'?t.date.startsWith(month.slice(0,4)):t.date.startsWith(month)),t=totals(ts),groups=groupCategories(ts.filter(t=>t.type==='expense')),max=groups[0]?.amount||1;const start=reportPeriod==='year'?`${month.slice(0,4)}-01`:shiftMonth(month,-5);const months=Array.from({length:reportPeriod==='year'?12:6},(_,i)=>shiftMonth(start,i));const sums=months.map(m=>totals(state.transactions.filter(t=>t.date.startsWith(m))));const maxBar=Math.max(...sums.flatMap(x=>[x.income,x.expense]),1);const days=reportPeriod==='year'?Math.round((new Date(Number(month.slice(0,4))+1,0,1)-new Date(Number(month.slice(0,4)),0,1))/864e5):month===monthNow()?Number(today().slice(8)):new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const rate=t.income?Math.round((t.income-t.expense)/t.income*100):null;return `<div class="page-title"><div><p class="eyebrow">SEE THE BIGGER PICTURE</p><h1>每一笔，都有答案<span class="orange-dot">.</span></h1></div></div><div class="section-line">${monthPicker()}<div class="segmented compact">${btn('period','月度',reportPeriod==='month'?'selected':'','data-value="month"')}${btn('period','年度',reportPeriod==='year'?'selected':'','data-value="year"')}</div></div><section class="stats-grid"><div><small>总支出</small><strong>¥ ${money(t.expense)}</strong></div><div><small>总收入</small><strong class="positive">¥ ${money(t.income)}</strong></div><div><small>日均支出</small><strong>¥ ${money(Math.round(t.expense/days))}</strong></div><div><small>结余率</small><strong>${rate===null?'—':rate+'%'}</strong></div></section><section class="card chart-card"><div class="section-line"><h2>${reportPeriod==='year'?'全年':'近 6 个月'}收支趋势</h2><div class="legend"><span><i></i>支出</span><span><i></i>收入</span></div></div><div class="bar-chart" aria-label="每月收支柱状图">${months.map((m,i)=>`<div class="bar-column" title="${m} 支出 ${money(sums[i].expense)} 收入 ${money(sums[i].income)}"><div class="bars"><i style="height:${Math.max(sums[i].expense?2:0,sums[i].expense/maxBar*100)}%"></i><i style="height:${Math.max(sums[i].income?2:0,sums[i].income/maxBar*100)}%"></i></div><small>${Number(m.slice(5))}月</small></div>`).join('')}</div><details class="chart-details"><summary>查看每月金额</summary><table><thead><tr><th>月份</th><th>支出</th><th>收入</th></tr></thead><tbody>${months.map((m,i)=>`<tr><td>${m}</td><td>${money(sums[i].expense)}</td><td>${money(sums[i].income)}</td></tr>`).join('')}</tbody></table></details></section><section class="card chart-card"><div class="section-line"><h2>钱都花在哪儿</h2><span class="caption">支出分类</span></div>${groups.length?`<div class="donut-wrap"><div class="donut" role="img" aria-label="支出分类占比" style="background:conic-gradient(${(()=>{let p=0;return groups.map((g,i)=>{const old=p;p+=g.amount/t.expense*100;return `${palette[i%palette.length]} ${old}% ${p}%`;}).join(',');})()})"><div><small>总支出</small><strong>¥${money(t.expense)}</strong></div></div><div class="donut-note"><span>TOP 01</span><strong>${esc(groups[0].name)}</strong><small>占总支出 ${Math.round(groups[0].amount/t.expense*100)}%</small></div></div><div class="category-ranking">${groups.map((g,i)=>`<div class="rank-row"><span class="rank-dot" style="background:${palette[i%palette.length]}"></span><div><div class="section-line"><strong>${esc(g.name)} <small>${Math.round(g.amount/t.expense*100)}%</small></strong><b>¥ ${money(g.amount)}</b></div><div class="progress"><i style="width:${g.amount/max*100}%;background:${palette[i%palette.length]}"></i></div></div></div>`).join('')}</div>`:empty('还没有支出数据','记录后自动生成分类占比和趋势。','', '')}</section><section class="card insight-card"><div class="insight-symbol">✦</div><div><span class="eyebrow">${reportPeriod==='year'?'年度观察':'月度观察'}</span><p>${reportPeriod==='year'?`全年已记录 ${ts.length} 笔账单，结余 ¥${money(t.income-t.expense)}。${t.income?'结余率按（收入 − 支出）÷ 收入计算。':'记录收入后可计算结余率。'}`:insight(ts)}</p></div></section>${btn('budget',`${icon('wallet',19)} 管理 ${labelMonth()}预算 ${icon('chevron',16)}`,'wide-row')}<p class="footnote">统计基于已记录账单；转账不计入收支。日均支出按所选期间天数计算，当月截至今天。</p>`;}
function accountsView(){const total=sumAccounts(),assets=state.accounts.reduce((n,a)=>n+Math.max(0,balance(state,a.id)),0),debt=assets-total;return `<div class="page-title"><div><p class="eyebrow">A PLACE FOR EVERY PENNY</p><h1>我的账户<span class="orange-dot">.</span></h1></div>${btn('add-account',icon('plus'),'icon-button','aria-label="新增账户"')}</div><section class="asset-card"><span>净资产</span><h2>¥ ${money(total)}</h2><div><span>总资产 <b>¥ ${money(assets)}</b></span><span>总负债 <b>¥ ${money(debt)}</b></span></div></section><div class="section-line section-title"><h2>账户列表</h2><span class="caption">${state.accounts.length} 个账户</span></div><section class="account-list">${state.accounts.map((a,i)=>`<button class="account-card" data-action="edit-account" data-id="${esc(a.id)}"><span class="account-icon" style="background:${['#e6efea','#f6ebdf','#e7edf4'][i%3]}">${icon('wallet',23)}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.kind)}</small></div><b class="${balance(state,a.id)<0?'negative':''}">¥ ${money(balance(state,a.id))}</b>${icon('chevron',15)}</button>`).join('')}</section>${btn('add-account',icon('plus',19)+' 新增账户','dashed-button')}${btn('transfer',icon('repeat',19)+' 账户之间转一笔','wide-row')}<p class="footnote">账户余额 = 初始余额 + 收入 − 支出 + 转入 − 转出。信用卡欠款以负数填写，还款使用转账。</p>`;}
function settingsView(){return `<div class="page-title"><div><p class="eyebrow">MADE TO BE YOURS</p><h1>把账本照顾好<span class="orange-dot">.</span></h1></div></div><section class="profile-card"><span class="brand-mark large">${icon('list',29)}</span><div><h2>${esc(state.settings.name)}</h2><p>${state.transactions.length} 笔账单 · 人民币 CNY</p></div>${btn('rename',icon('edit',18),'icon-button','aria-label="修改账本名称"')}</section><div class="settings-group">${settingRow('shortcut-help','tag','截图记账快捷指令','微信 / 支付宝 · 识别后确认入账')}${settingRow('backup','cloud','备份与恢复','导出到 iCloud 云盘，随时找回')}${settingRow('budget','wallet','预算管理','月度总预算与分类预算')}${settingRow('rules','repeat','周期账单',`${state.rules.length} 项计划 · 打开时确认入账`)}${settingRow('categories','tag','分类管理','让每一笔都各归其位')}${settingRow('export-csv','download','导出表格','CSV 格式，便于进一步分析')}</div><div class="settings-group">${toggleSettingRow('replace-backup','shield','固定备份文件名','保存同名文件时，需在系统中确认替换',state.settings.replaceBackup)}${settingRow('install','plus','添加到 iPhone 主屏幕','全屏打开，离线也能记')}${settingRow('persist','shield','申请持久存储','由系统决定是否授予，仍需备份')}${settingRow('demo','sun','体验示例账本','与真实数据分开，放心体验')}${swWaiting||reloadAvailable?settingRow('update','download','发现新版本','更新应用，保留本地账本'):''}<p class="footnote update-status" role="status">${esc(updateStatus)}</p></div><section class="card backup-explainer"><h3>${icon('shield',18)} 你的数据，由你掌握</h3><p>账本保存在当前浏览器的本地数据库中，不上传到服务器。清理网站数据、更换网址或设备会影响访问，请定期备份。</p><p>备份请保存到 iCloud 云盘中的“轻账”文件夹。固定文件名默认开启；同名时请在系统中选择替换，下载可能生成副本。网页不能自动写入这个目录或清理旧文件。加密密码无法找回。</p></section><p class="privacy-footer">轻账 ${__APP_VERSION__} · 简单记录，认真生活</p>`;}
function settingRow(action,ic,title,subtitle){return `<button class="setting-row" data-action="${action}"><span class="setting-icon">${icon(ic,21)}</span><span><strong>${title}</strong><small>${subtitle}</small></span>${icon('chevron',17)}</button>`;}
function toggleSettingRow(action,ic,title,subtitle,checked){return `<button class="setting-row toggle-row" data-action="${action}" aria-pressed="${checked}"><span class="setting-icon">${icon(ic,21)}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span class="toggle ${checked?'on':''}" aria-hidden="true"><i></i></span></button>`;}
function transactionForm(id=null,type='expense',draft=null){const old=state.transactions.find(t=>t.id===id);const t=old||draft||{type,amount:0,date:today(),accountId:state.accounts[0].id,categoryId:sortedCategories(state,type)[0]?.id,note:''};modalContext={kind:'tx',id,captureId:t.captureId};openModal(old?'编辑账单':draft?'确认识别结果':'记下这一笔',`${draft?captureReview(draft):!old?btn('capture','从付款截图文字记账','secondary full'):''}<form id="tx-form"><div class="segmented form-tabs">${[['expense','支出'],['income','收入'],['transfer','转账']].map(([k,l])=>`<button type="button" data-action="tx-type" data-value="${k}" class="${t.type===k?'selected':''}">${l}</button>`).join('')}</div><input type="hidden" name="type" value="${t.type}"><label class="amount-input"><span>¥</span><input name="amount" inputmode="decimal" placeholder="0.00" value="${t.amount?(t.amount/100).toFixed(2):''}" required autocomplete="off" aria-label="金额"></label><div id="tx-categories">${categoryFields(t)}</div><div class="form-grid"><label>日期<input type="date" name="date" value="${t.date}" min="1900-01-01" max="${today()}" required></label><label>${t.type==='transfer'?'转出账户':'账户'}<select name="accountId" required>${draft&&!t.accountId?'<option value="" disabled selected>请选择实际收付款账户</option>':''}${accountOptions(t.accountId)}</select></label></div><label>备注<input name="note" maxlength="300" placeholder="这一笔，是生活里的什么？" value="${esc(t.note)}"></label><p class="form-error" role="alert"></p><button type="submit" class="primary full">${icon('check',19)} ${old?'保存修改':'保存账单'}</button>${draft?'<p class="footnote">识别仅作建议；请核对金额、日期、收支和实际使用的账户，再保存。</p>':''}${old?btn('delete-tx',icon('trash',16)+' 删除这笔账单','danger-link',`type="button" data-id="${esc(id)}"`):''}</form>`);}
function accountOptions(id){return state.accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)}</option>`).join('');}
function categoryFields(t,expanded=false){if(t.type==='transfer')return `<label>转入账户<select name="toAccountId">${accountOptions(t.toAccountId||state.accounts.find(a=>a.id!==t.accountId)?.id)}</select></label><p class="footnote">转账不计入收入和支出。</p>`;const categories=sortedCategories(state,t.type),selected=categories.find(c=>c.id===t.categoryId)||categories[0],collapsible=categories.length>10,hiddenSelection=collapsible&&!expanded&&categories.indexOf(selected)>=9;return `<label>分类${hiddenSelection?` · 已选：${esc(selected.name)}`:''}</label><div class="category-grid" id="category-choices">${categories.map((c,i)=>`<label class="category-choice" ${collapsible&&!expanded&&i>=9?'hidden':''}><input type="radio" name="categoryId" value="${esc(c.id)}" ${c.id===selected?.id?'checked':''} required><span>${symbols[c.name]||icon('tag',21)}<small>${esc(c.name)}</small></span></label>`).join('')}${collapsible?`<button type="button" class="category-toggle" data-action="toggle-categories" aria-expanded="${expanded}" aria-controls="category-choices">${icon(expanded?'up':'down',22)}<small>${expanded?'收起':'展开'}</small></button>`:''}</div>`;}

function captureModal(){openModal('截图记账',`<p class="soft-note">正在请求读取剪贴板。如系统显示“粘贴”，请点击允许；随后直接生成待确认账单，不会自动入账。</p>${btn('capture-paste',icon('download',18)+' 重试读取剪贴板','primary full')}<form id="capture-form"><label>付款或收款页面的文字<textarea name="text" maxlength="20000" rows="7" required placeholder="也可以长按这里粘贴，例如：&#10;微信支付&#10;支付成功&#10;¥ 28.50&#10;商户名称：咖啡店"></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="secondary full">识别文字</button></form>${btn('shortcut-help','安装截图识别快捷指令','text-button')}<p class="footnote">截图由 iPhone 本地识字；轻账不上传识别内容。只保存确认后的账单，不保存整段截图文字。</p>`);}
function captureText(raw){return String(raw||'').replace(new RegExp('^'+CAPTURE_MARKER+'\\s*'),'').normalize('NFKC').replace(/[−–]/g,'-').replace(/\r/g,'').trim();}
async function pasteCapture(){
 const form=document.querySelector('#capture-form');if(!form||form.dataset.reading)return;
 form.dataset.reading='1';const field=form.elements.text,button=modalRoot.querySelector('[data-action="capture-paste"]');
 if(button)button.disabled=true;
 try{
  // Invoke in the original click handler, before any async work, to retain iOS user activation.
  const value=await navigator.clipboard.readText();
  if(!form.isConnected)return;
  if(!captureText(value)){form.querySelector('.form-error').textContent='剪贴板为空，请先运行截图识别快捷指令，或在下方粘贴文字。';return;}
  field.value=value;form.requestSubmit();
 }catch{if(form.isConnected){form.querySelector('.form-error').textContent='未能读取剪贴板，请重试，或长按文字框选择“粘贴”，然后点“识别文字”。';}}
 finally{delete form.dataset.reading;if(button)button.disabled=false;}
}
function captureReview(draft){return `<div class="soft-note"><strong>${draft.platform?esc(draft.platform)+' · ':''}请核对识别结果</strong>${draft.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div>${draft.candidates.length>1?`<div class="capture-candidates">${draft.candidates.map(c=>btn('capture-amount','¥ '+money(c.amount),'secondary small',`data-value="${c.amount}" title="${esc(c.label)}"`)).join('')}</div>`:''}`;}
function shortcutHelp(){openModal('截图记账快捷指令',`<div class="soft-note">支持微信支付与支付宝的付款、收款文字。识别只是建议，必须核对后保存。快捷指令不能直接写入主屏幕网页账本。</div><a class="primary full" href="./shortcuts/qingzhang-capture.shortcut" download="轻账截图识别.shortcut">下载“轻账截图识别”</a><ol class="steps"><li><b>1</b><div><strong>下载安装快捷指令</strong><p>下载后在“文件”中打开 .shortcut 文件，选择添加。首次运行按 iOS 提示允许截屏和识别。</p></div></li><li><b>2</b><div><strong>绑定轻点背面或操作按钮</strong><p>iPhone 设置 → 辅助功能 → 触控 → 轻点背面 → 轻点两下 → 选择“轻账截图识别”。也可在操作按钮设置中选择该快捷指令。</p></div></li><li><b>3</b><div><strong>停留在支付结果页再触发</strong><p>快捷指令截取当前屏幕、提取文字并复制；不自动保存截图到相册，不上传截图。</p></div></li><li><b>4</b><div><strong>自动返回轻账并识别</strong><p>点击“截图记账”立即请求剪贴板；如系统显示“粘贴”，点允许后直接进入确认页。核对金额、收支、分类、日期和账户后保存。</p></div></li></ol><details class="chart-details"><summary>文件无法安装？手动配置快捷指令</summary><p class="footnote">在“快捷指令”App 新建：① 截屏 ② 从图像中提取文本（输入选择上一动作的截屏）③ 拷贝至剪贴板（输入选择提取的文本，开启“仅本地”）请在复制前添加“文本”动作：第一行填写“此剪切板记录为轻账专用”，下一行插入“从图像中提取的文本”变量。将这段文本拷贝至剪贴板；最后用“打开 URL”打开 webapp://miaodidi.github.io/qingzhang/。</p></details><p class="footnote">通过 webapp:// 尝试唤起已安装的轻账；此方式已由用户在 iPhone 验证，其他系统版本可能不同。仅在你点击截图记账时读取剪贴板，启动和返回前台时不读取；保存后保留防重复检查，不再次读写剪贴板。受保护的页面可能无法截屏或识字，可手动记账。</p>`);}
function budgetForm(){const b=state.budgets[month]||{total:0,categories:{}},t=totals(monthTransactions());openModal(`${month.slice(0,4)}年${labelMonth()}预算`,`<form id="budget-form"><div class="soft-note">本月已支出 <strong>¥ ${money(t.expense)}</strong>。留空或填 0 表示不设置预算。</div><label>月度总预算（元）<input name="total" inputmode="decimal" value="${b.total?b.total/100:''}" placeholder="例如 5000"></label><h3 class="form-section-title">分类预算</h3><div class="budget-fields">${sortedCategories(state,'expense').map(c=>{const spent=monthTransactions().filter(t=>t.type==='expense'&&t.categoryId===c.id).reduce((n,t)=>n+t.amount,0),limit=b.categories[c.id];return `<label><span>${symbols[c.name]||'◈'} ${esc(c.name)}<small class="${limit&&spent>limit?'negative':''}">已用 ¥${money(spent)}${limit?' / '+Math.round(spent/limit*100)+'%':''}</small></span><input name="cat-${esc(c.id)}" aria-label="${esc(c.name)}预算" inputmode="decimal" placeholder="不限" value="${limit?limit/100:''}"></label>`;}).join('')}</div><p class="footnote">分类预算独立提醒；总预算由你设置，不自动相加。</p><p class="form-error" role="alert"></p><button class="primary full" type="submit">保存预算</button></form>`);}
function accountForm(id){const a=state.accounts.find(a=>a.id===id)||{name:'',kind:'银行卡',opening:0};modalContext={kind:'account',id};openModal(id?'编辑账户':'添加账户',`<form id="account-form"><label>账户名称<input name="name" maxlength="30" value="${esc(a.name)}" placeholder="例如：招商银行、支付宝" required></label><label>账户类型<select name="kind">${['银行卡','现金','支付宝','微信','信用卡','储蓄','其他'].map(k=>`<option ${k===a.kind?'selected':''}>${k}</option>`).join('')}</select></label><label>初始余额（元）<input name="opening" inputmode="text" value="${a.opening/100}" required></label><p class="footnote">填写开始记账之前的余额，欠款填负数。修改初始余额会同时调整当前余额。</p><p class="form-error" role="alert"></p><button class="primary full">保存账户</button>${id?btn('delete-account','删除账户','danger-link',`type="button" data-id="${esc(id)}"`):''}</form>`);}
function categoriesModal(){openModal('分类管理',`<div class="soft-note">按全部账目的使用次数排序。有账单、预算或周期计划使用的分类不能删除。</div>${['expense','income'].map(type=>`<h3 class="form-section-title">${type==='expense'?'支出':'收入'}分类</h3><div class="category-manage">${sortedCategories(state,type).map(c=>`<div><span>${symbols[c.name]||'◈'} ${esc(c.name)}</span><button data-action="rename-category" data-id="${esc(c.id)}" aria-label="重命名${esc(c.name)}">${icon('edit',17)}</button><button data-action="delete-category" data-id="${esc(c.id)}" aria-label="删除${esc(c.name)}">${icon('close',17)}</button></div>`).join('')}</div>`).join('')}<form id="category-form"><h3 class="form-section-title">新增分类</h3><div class="form-grid"><label>名称<input name="name" maxlength="20" required placeholder="例如：宠物"></label><label>类型<select name="type"><option value="expense">支出</option><option value="income">收入</option></select></label></div><p class="form-error" role="alert"></p><button class="primary full">添加分类</button></form>`);}
function rulesModal(){openModal('周期账单',`<p class="soft-note">适合房租、订阅、工资等。到期后在这里确认入账；关闭应用时不会自动记账或推送通知。</p><div class="rule-list">${state.rules.length?state.rules.map(r=>`<div class="rule-card"><div class="section-line"><strong>${esc(r.note||cat(r.categoryId)?.name)}</strong><b>${r.type==='income'?'+':'−'}${money(r.amount)}</b></div><p>${{daily:'每天',weekly:'每周',monthly:'每月'}[r.frequency]} · 下次 ${r.next} · ${esc(account(r.accountId)?.name)}</p><div class="rule-actions">${r.next<=today()?btn('post-rule','确认本期入账','primary small',`data-id="${esc(r.id)}"`):'<span class="caption">尚未到期</span>'}${btn('skip-rule','跳过一期','text-button',`data-id="${esc(r.id)}"`)}${btn('delete-rule','删除','danger-link',`data-id="${esc(r.id)}"`)}</div></div>`).join(''):empty('把固定开销安排好','添加周期计划，到期后轻松确认。','','')}</div>${btn('add-rule',icon('plus',18)+' 新建周期账单','primary full')}`);}
function ruleForm(){openModal('新建周期账单',`<form id="rule-form"><label>名称<input name="note" maxlength="100" placeholder="例如：每月房租" required></label><div class="form-grid"><label>类型<select name="type" id="rule-type"><option value="expense">支出</option><option value="income">收入</option></select></label><label>金额（元）<input name="amount" inputmode="decimal" required placeholder="0.00"></label></div><div class="form-grid"><label>分类<select name="categoryId" id="rule-category">${ruleCategoryOptions('expense')}</select></label><label>账户<select name="accountId">${accountOptions()}</select></label></div><div class="form-grid"><label>周期<select name="frequency"><option value="monthly">每月</option><option value="weekly">每周</option><option value="daily">每天</option></select></label><label>首次日期<input name="next" type="date" min="1900-01-01" max="2200-12-31" required value="${today()}"></label></div><p class="footnote">月末日期会对齐目标月份的最后一天，后续按该日期继续。</p><p class="form-error" role="alert"></p><button class="primary full">保存周期账单</button></form>`);}
function ruleCategoryOptions(type){return sortedCategories(state,type).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');}
function backupModal(){if(demo){toast('请先退出演示，再备份你的真实账本');return;}openModal('备份与恢复',`<section class="backup-status">${icon('shield',27)}<div><strong>${state.settings.lastBackup?'最近导出 '+new Date(state.settings.lastBackup).toLocaleDateString('zh-CN'):'还没有导出过备份'}</strong><p>导出完成不代表已存入 iCloud，请在“文件”中核对。</p></div></section><h3 class="form-section-title">备份整个账本</h3><p class="footnote">包含账户、分类、全部账单、预算和周期计划。可选择加密，密码丢失后无法恢复。</p><form id="backup-form"><label>加密密码（可选，至少 8 位）<input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="留空导出未加密备份"></label><label>再输入一次密码<input name="confirm" type="password" autocomplete="new-password" placeholder="使用加密时填写"></label><p class="form-error" role="alert"></p><button class="primary full">${icon('download',19)} 生成备份文件</button></form><div id="backup-ready"></div><div class="divider"></div><h3>恢复账本</h3><p class="footnote">选择轻账 JSON 备份。先核对内容再恢复；恢复会替换当前账本，建议先导出当前数据。</p><form id="import-form"><label class="file-label">${icon('upload',20)} 选择备份文件<input type="file" name="file" accept=".json,application/json" required></label><label>备份密码（加密文件需要）<input name="password" type="password" autocomplete="off" placeholder="未加密则留空"></label><p class="form-error" role="alert"></p><button class="secondary full">读取并检查备份</button></form>`);}
let deliveringBackup=false;
async function deliverBackup(share){
 if(!backupReady||deliveringBackup)return;
 deliveringBackup=true;
 const f=backupReady;
 const buttons=[...modalRoot.querySelectorAll('[data-action="share-backup"],[data-action="download-backup"]')];
 buttons.forEach(b=>b.disabled=true);
 try{
  if(share&&navigator.canShare?.({files:[f]})){
   try{await navigator.share({files:[f]});await markBackup();toast('分享已完成，请在 iCloud 云盘核对文件');}
   catch(e){if(e.name!=='AbortError')toast('分享未完成，可以使用下载备份');}
  }else{download(f,f.name);await markBackup();toast('已发起一次下载；不必再点分享，请确认文件已保存');}
 }finally{
  // Prevent a rapid second tap from starting another save dialog or download.
  setTimeout(()=>{deliveringBackup=false;buttons.forEach(b=>b.disabled=false);},1200);
 }
}
async function markBackup(){await commit(s=>{s.settings.lastBackup=new Date().toISOString();});}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function installModal(){openModal('装进你的 iPhone',`<div class="install-icon"><span class="brand-mark large">${icon('list',30)}</span><h3>轻账</h3><p>你的私人随身账本</p></div><ol class="steps"><li><b>1</b><div><strong>用 Safari 打开正式网址</strong><p>首次需联网，等页面完整加载。</p></div></li><li><b>2</b><div><strong>轻点“分享” ${icon('upload',16)}</strong><p>在菜单中找到“添加到主屏幕”。</p></div></li><li><b>3</b><div><strong>确认名称，轻点“添加”</strong><p>以后从主屏幕图标进入，可全屏离线记账。</p></div></li><li><b>4</b><div><strong>定期把备份存到 iCloud 云盘</strong><p>备份与恢复 → 生成文件 → 分享 → 存储到“文件” → iCloud 云盘。</p></div></li></ol><div class="soft-note">请始终使用同一个正式网址和主屏幕入口。不同网址、浏览器或入口可能有各自的本地数据。</div>`);}
function confirmModal(title,message,action,id,label='确认删除'){openModal(title,`<p class="confirm-copy">${esc(message)}</p><div class="confirm-actions">${btn('close','取消','secondary')}${btn(action,label,'primary',id?`data-id="${esc(id)}"`:'')}</div>`);}
function renameModal(kind,id){const value=kind==='category'?cat(id).name:state.settings.name;modalContext={kind,id};openModal(kind==='category'?'重命名分类':'账本名称',`<form id="rename-form"><label>名称<input name="name" maxlength="${kind==='category'?20:30}" value="${esc(value)}" required></label><p class="form-error" role="alert"></p><button class="primary full">保存名称</button></form>`);}
function showDemo(){if(demo){tab='home';render();return;}realState=state;state=initialState();state.settings.name='生活示例账本';state.accounts=[{id:'demo-bank',name:'日常银行卡',kind:'银行卡',opening:1280000},{id:'demo-wallet',name:'微信钱包',kind:'微信',opening:68000}];const now=today();for(let mi=0;mi<6;mi++){const m=shiftMonth(monthNow(),-mi);const add=(day,type,amount,categoryId,note,accountId='demo-bank')=>{const date=`${m}-${String(day).padStart(2,'0')}`;if(date<=now)state.transactions.push({id:uid(),date,type,amount,categoryId,note,accountId,createdAt:date});};add(1,'income',1200000,'i0','每月的一份底气');add(2,'expense',280000,'e3','温暖的小家 · 房租');add(3,'expense',3890+mi*800,'e0','周末的美味');add(5,'expense',12900+mi*500,'e1','给生活添点新意');add(8,'expense',3200,'e2','城市漫游');add(10,'expense',8600,'e4','电影和爆米花');add(15,'expense',19800,'e6','认真学习一点新东西');add(19,'expense',29900,'e1','入秋的新衣');add(22,'expense',6800,'e0','和朋友好好吃饭');add(24,'expense',2600,'e0','一杯拿铁','demo-wallet');add(26,'expense',3500,'e2','下班回家');add(28,'expense',4800,'e0','热气腾腾的晚餐');}state.budgets[monthNow()]={total:600000,categories:{e0:100000,e1:80000}};demo=true;month=monthNow();tab='home';render();toast('这是独立演示账本，可自由体验');}
async function onAction(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;if(el.tagName==='A')e.preventDefault();if(['home','ledger','reports','accounts','settings'].includes(a)){tab=a;if(a==='ledger'&&month>monthNow())month=monthNow();render();window.scrollTo({top:0});if(a==='settings')void checkForUpdate();return;}if(a==='clear-search'){const input=document.querySelector('#search');if(input){input.focus({preventScroll:true});input.value='';delete input.dataset.composing;refreshSearch(input);}return;}if(a==='capture'){captureModal();await pasteCapture();return;}if(a==='shortcut-help'){shortcutHelp();return;}if(a==='capture-paste'){await pasteCapture();return;}if(a==='capture-amount'){document.querySelector('#tx-form [name=amount]').value=(Number(v)/100).toFixed(2);toast('金额已更改，请核对');return;}if(a==='close'){closeModal();return;}if(a==='add'||a==='transfer'){transactionForm(null,a==='transfer'?'transfer':'expense');return;}if(a==='edit-tx'){transactionForm(id);return;}if(a==='toggle-categories'){const form=document.querySelector('#tx-form');document.querySelector('#tx-categories').innerHTML=categoryFields({type:form.elements.type.value,categoryId:form.elements.categoryId.value},el.getAttribute('aria-expanded')!=='true');document.querySelector('[data-action=toggle-categories]').focus({preventScroll:true});return;}if(a==='tx-type'){const form=document.querySelector('#tx-form');form.elements.type.value=v;form.querySelectorAll('[data-action="tx-type"]').forEach(b=>b.classList.toggle('selected',b.dataset.value===v));document.querySelector('#tx-categories').innerHTML=categoryFields({type:v,accountId:form.elements.accountId.value,categoryId:sortedCategories(state,v)[0]?.id});return;}if(a==='ledger-current'||a==='ledger-all'){ledgerAll=a==='ledger-all';month=monthNow();render();return;}if(a==='prev-month'||a==='next-month'){if(tab==='ledger'){if(ledgerAll){if(a==='prev-month'){ledgerAll=false;month=monthNow();}}else if(a==='next-month'&&month>=monthNow()){month=monthNow();ledgerAll=true;}else if(a==='next-month'||month>'1900-01')month=shiftMonth(month,a==='prev-month'?-1:1);}else if(a==='next-month'||month>'1900-01')month=shiftMonth(month,a==='prev-month'?-1:1);render();return;}if(a==='filter'){filter=v;render();return;}if(a==='period'){reportPeriod=v;render();return;}if(a==='budget'){budgetForm();return;}if(a==='add-account'||a==='edit-account'){accountForm(id);return;}if(a==='categories'){categoriesModal();return;}if(a==='rules'){rulesModal();return;}if(a==='add-rule'){ruleForm();return;}if(a==='backup'){backupModal();return;}if(a==='share-backup'||a==='download-backup'){await deliverBackup(a==='share-backup');return;}if(a==='install'){installModal();return;}if(a==='demo'){showDemo();return;}if(a==='exit-demo'){state=await openStore();realState=null;demo=false;month=monthNow();tab='home';closeModal();render();return;}if(a==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'已获得持久存储；请继续定期备份':'系统暂未授予持久存储，请保留外部备份');return;}if(a==='replace-backup'){if(await commit(s=>{s.settings.replaceBackup=!s.settings.replaceBackup;}))toast(state.settings.replaceBackup?'已开启固定文件名备份':'已关闭固定文件名备份');return;}if(a==='rename'||a==='rename-category'){renameModal(a==='rename'?'book':'category',id);return;}
if(a==='export-csv'){download(new Blob([csv(state)],{type:'text/csv;charset=utf-8'}),`轻账-全部明细-${today()}.csv`);toast('已导出全部账单明细；完整恢复请使用 JSON 备份');return;}
if(a==='delete-tx'){confirmModal('删除这笔账单？','删除后将重新计算账户余额和统计。','confirm-delete-tx',id);return;}if(a==='confirm-delete-tx'){if(await commit(s=>{s.transactions=s.transactions.filter(t=>t.id!==id);})) {closeModal();toast('账单已删除');}return;}
if(a==='delete-account'){confirmModal('删除这个账户？','仅能删除没有账单和周期计划关联的账户，至少保留一个账户。','confirm-delete-account',id);return;}if(a==='confirm-delete-account'){if(await commit(s=>{if(s.accounts.length<=1)throw Error('至少需要保留一个账户');if(s.transactions.some(t=>t.accountId===id||t.toAccountId===id)||s.rules.some(r=>r.accountId===id))throw Error('此账户仍有关联账单或周期计划，不能删除');s.accounts=s.accounts.filter(a=>a.id!==id);})){closeModal();toast('账户已删除');}return;}
if(a==='delete-category'){if(await commit(s=>{if(s.transactions.some(t=>t.categoryId===id)||s.rules.some(r=>r.categoryId===id)||Object.values(s.budgets).some(b=>Object.hasOwn(b.categories,id)))throw Error('此分类仍被账单、计划或预算使用');const c=s.categories.find(c=>c.id===id);if(s.categories.filter(x=>x.type===c.type).length<=1)throw Error('每种类型至少保留一个分类');s.categories=s.categories.filter(c=>c.id!==id);})){categoriesModal();toast('分类已删除');}return;}
if(a==='delete-rule'){confirmModal('删除周期计划？','已入账的账单会保留。','confirm-delete-rule',id);return;}if(a==='confirm-delete-rule'){if(await commit(s=>{s.rules=s.rules.filter(r=>r.id!==id);})){rulesModal();toast('计划已删除');}return;}
if(a==='post-rule'||a==='skip-rule'){const r=state.rules.find(r=>r.id===id);if(!r)return;const expected=r.next;if(a==='skip-rule'){modalContext={expected};confirmModal('跳过这一期？',`跳过 ${r.next} 的计划，不会生成账单。`,'confirm-skip-rule',id,'确认跳过');modalContext={expected};return;}if(await commit(s=>{const r=s.rules.find(r=>r.id===id);if(!r||r.next!==expected)throw Error('此计划已更新，请重试');if(r.next>today())throw Error('此计划尚未到期');const rid=`${r.id}:${r.next}`;if(!s.transactions.some(t=>t.ruleOccurrence===rid))s.transactions.push({id:uid(),type:r.type,amount:r.amount,categoryId:r.categoryId,accountId:r.accountId,date:r.next,note:r.note,createdAt:new Date().toISOString(),ruleOccurrence:rid});r.next=nextDate(r.next,r.frequency);})){rulesModal();toast('本期已入账');}return;}
if(a==='confirm-skip-rule'){const expected=modalContext?.expected;if(await commit(s=>{const r=s.rules.find(r=>r.id===id);if(!r||r.next!==expected)throw Error('计划已更新，请重新打开');r.next=nextDate(r.next,r.frequency);})){rulesModal();toast('已跳过一期');}return;}
if(a==='confirm-import'){const imported=importData;if(!imported)return;if(await commit(()=>structuredClone(imported))){closeModal();month=monthNow();tab='home';render();toast('账本已恢复');}return;}
if(a==='update'){updateRequested=true;if(swWaiting)swWaiting.postMessage({type:'SKIP_WAITING'});else if(reloadAvailable)location.reload();return;}}
document.addEventListener('click',e=>{onAction(e).catch(err=>toast(err.message||'操作未完成，请重试'));});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&modalRoot.firstChild){const list=[...modalRoot.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
function updateSearchClear(input){const clear=document.querySelector('[data-action=clear-search]');if(clear)clear.hidden=!input.value;}
function refreshSearch(input){query=input.value;updateSearchClear(input);const template=document.createElement('template');template.innerHTML=ledgerView();for(const id of ['ledger-count','ledger-results']){const current=document.getElementById(id),next=template.content.querySelector('#'+id);if(current&&next)current.replaceWith(next);}}
document.addEventListener('compositionstart',e=>{if(e.target.id==='search')e.target.dataset.composing='true';});
document.addEventListener('compositionend',e=>{if(e.target.id==='search'){delete e.target.dataset.composing;refreshSearch(e.target);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){updateSearchClear(e.target);if(!e.isComposing&&!e.target.dataset.composing)refreshSearch(e.target);}});
document.addEventListener('search',e=>{if(e.target.id==='search'&&!e.target.dataset.composing)refreshSearch(e.target);});
document.addEventListener('change',e=>{if(e.target.id==='month-input'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=tab==='ledger'&&e.target.value>monthNow()?monthNow():e.target.value;if(tab==='ledger')ledgerAll=false;render();}if(e.target.id==='account-filter'){accountFilter=e.target.value;render();}if(e.target.id==='rule-type')document.querySelector('#rule-category').innerHTML=ruleCategoryOptions(e.target.value);});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),error=f.querySelector('.form-error'),submit=f.querySelector('[type="submit"],button:not([type])');if(busy||f.dataset.submitting)return;f.dataset.submitting='1';if(submit)submit.disabled=true;try{if(error)error.textContent='';
if(f.id==='capture-form'){const rawCapture=captureText(d.text);const result=parsePaymentText(rawCapture);const captureId=await captureFingerprint(result.normalized);if(state.transactions.some(t=>t.captureId===captureId))throw Error('这份识别文字已经入账，请到明细查看，避免重复记录');const category=state.categories.find(c=>c.type===result.type&&c.name===result.category)||state.categories.find(c=>c.type===result.type&&['其他','其他收入'].includes(c.name))||state.categories.find(c=>c.type===result.type);transactionForm(null,result.type,{...result,normalized:undefined,categoryId:category?.id,accountId:(state.accounts.find(a=>a.name==='日常账户')||state.accounts[0]).id,captureId});}
if(f.id==='tx-form'){const amount=cents(d.amount);if(amount<=0)throw Error('金额需大于 0');if(!validDate(d.date)||d.date>today())throw Error('请选择今天或之前的有效日期');if(d.type==='transfer'&&d.accountId===d.toAccountId)throw Error('转入与转出账户不能相同');const id=modalContext?.id,captureId=modalContext?.captureId;const t={id:id||uid(),type:d.type,amount,date:d.date,accountId:d.accountId,note:d.note.trim(),...(captureId?{captureId}:{}),...(d.type==='transfer'?{toAccountId:d.toAccountId}:{categoryId:d.categoryId}),createdAt:new Date().toISOString()};if(await commit(s=>{if(captureId&&s.transactions.some(x=>x.captureId===captureId&&x.id!==id))throw Error('这份识别结果已经入账，未重复保存');const i=s.transactions.findIndex(x=>x.id===id);if(id&&i<0)throw Error('账单已被删除，请重新打开');if(i>=0)s.transactions[i]={...s.transactions[i],...t};else s.transactions.push(t);if(captureId)s.settings.lastCaptureId=captureId;})){closeModal();toast(id?'账单已更新':'这一笔，记好了');}}
if(f.id==='budget-form'){const total=cents(d.total||'0'),categories={};if(total<0)throw Error('预算不能为负数');for(const c of sortedCategories(state,'expense')){const n=cents(d['cat-'+c.id]||'0');if(n<0)throw Error('分类预算不能为负数');if(n)categories[c.id]=n;}if(await commit(s=>{s.budgets[month]={total,categories};})){closeModal();toast('预算已保存');}}
if(f.id==='account-form'){if(!d.name.trim())throw Error('请填写账户名称');const id=modalContext?.id;const a={id:id||uid(),name:d.name.trim(),kind:d.kind,opening:cents(d.opening)};if(await commit(s=>{if(s.accounts.some(x=>x.name===a.name&&x.id!==a.id))throw Error('这个账户名称已存在');const i=s.accounts.findIndex(x=>x.id===id);if(id&&i<0)throw Error('账户已被删除');if(i>=0)s.accounts[i]=a;else s.accounts.push(a);})){closeModal();toast('账户已保存');}}
if(f.id==='category-form'){if(!d.name.trim())throw Error('请填写分类名称');if(await commit(s=>{if(s.categories.some(c=>c.name===d.name.trim()&&c.type===d.type))throw Error('这个分类已存在');s.categories.push({id:uid(),name:d.name.trim(),type:d.type});})){categoriesModal();toast('分类已添加');}}
if(f.id==='rename-form'){const ctx=modalContext;if(!d.name.trim())throw Error('名称不能为空');if(await commit(s=>{if(ctx.kind==='category'){const c=s.categories.find(c=>c.id===ctx.id);if(!c)throw Error('分类已被删除');if(s.categories.some(x=>x.id!==c.id&&x.type===c.type&&x.name===d.name.trim()))throw Error('分类名称已存在');c.name=d.name.trim();}else s.settings.name=d.name.trim();})){closeModal();toast('名称已保存');}}
if(f.id==='rule-form'){const amount=cents(d.amount);if(amount<=0)throw Error('金额需大于 0');if(!validDate(d.next))throw Error('请选择有效日期');if(!d.note.trim())throw Error('请填写计划名称');if(await commit(s=>{s.rules.push({...d,note:d.note.trim(),amount,id:uid()});})){rulesModal();toast('周期计划已保存');}}
if(f.id==='backup-form'){if(d.password&&d.password.length<8)throw Error('加密密码至少 8 位');if(d.password!==d.confirm)throw Error('两次密码不一致');const raw=await encodeBackup(state,d.password);const stamp=`${today()}-${new Date().toTimeString().slice(0,8).replaceAll(':','')}`;const fileName=state.settings.replaceBackup?'轻账-最新备份.json':`轻账${d.password?'-加密':''}-备份-${stamp}.json`;backupReady=new File([raw],fileName,{type:'application/json'});document.querySelector('#backup-ready').innerHTML=`<div class="soft-note success">${icon('check',18)} 备份文件已生成${d.password?'（已加密）':''}</div>${navigator.canShare?.({files:[backupReady]})?btn('share-backup','分享 / 存储到“文件”','primary full'):''}${btn('download-backup','下载备份文件','secondary full')}<p class="footnote">iPhone：选择“存储到文件” → iCloud 云盘 → 轻账 → 保存。${state.settings.replaceBackup?'文件名为“轻账-最新备份.json”；同名时请选择替换，下载可能生成副本。':'每次使用带日期的文件名。'}请在“文件”中核对保存结果。</p>`;document.querySelector('#backup-ready').scrollIntoView({behavior:'smooth',block:'nearest'});}
if(f.id==='import-form'){const file=f.elements.file.files[0];if(!file)throw Error('请选择备份文件');if(file.size>30*1024*1024)throw Error('备份文件超过 30 MB，暂不支持');const imported=await decodeBackup(await file.text(),d.password);openModal('确认恢复账本',`<div class="soft-note"><strong>${esc(imported.settings.name)}</strong><p>${imported.transactions.length} 笔账单 · ${imported.accounts.length} 个账户 · ${imported.rules.length} 个周期计划</p></div><p class="confirm-copy">恢复后会替换当前 ${state.transactions.length} 笔账单和所有设置。请确认已经备份当前账本。</p><div class="confirm-actions">${btn('close','取消','secondary')}${btn('confirm-import','替换并恢复','primary')}</div>`);importData=imported;}
}catch(err){if(error&&error.isConnected)error.textContent=err.message||'操作失败，请重试';else toast(err.message||'操作失败');}finally{delete f.dataset.submitting;if(submit)submit.disabled=false;}});
window.addEventListener('online',render);window.addEventListener('offline',render);
function setUpdateStatus(message){updateStatus=message;if(tab==='settings')render();}
function watchRegistration(reg){
 const refresh=()=>{
  if(reg.waiting){const fresh=swWaiting!==reg.waiting;swWaiting=reg.waiting;setUpdateStatus('新版本已下载，可以更新');if(fresh)toast('新版本已就绪，可在设置中更新');}
 };
 const watch=()=>{const w=reg.installing;if(!w){refresh();return;}setUpdateStatus('正在下载新版本…');w.addEventListener('statechange',()=>{
  if(w.state==='installed'){if(navigator.serviceWorker.controller){swWaiting=reg.waiting||w;setUpdateStatus('新版本已下载，可以更新');toast('新版本已就绪，可在设置中更新');}else setUpdateStatus('离线资源已准备好');}
  if(w.state==='redundant')setUpdateStatus('更新下载未完成，再点设置可重试');
 });};
 reg.addEventListener('updatefound',watch);refresh();if(reg.installing)watch();return reg;
}
function registerOffline(){
 if(!('serviceWorker' in navigator))return Promise.resolve(null);
 if(!offlineRegistration)offlineRegistration=navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`,{updateViaCache:'none'}).then(watchRegistration).catch(()=>{offlineRegistration=null;return null;});
 return offlineRegistration;
}
function checkForUpdate(){
 if(updateCheck)return updateCheck;
 setUpdateStatus('正在联网检查更新…');
 updateCheck=(async()=>{
  let timer;
  try{
   await Promise.race([(async()=>{
    const reg=await registerOffline();if(!reg)throw Error('unavailable');
    await reg.update();
    if(reg.waiting){swWaiting=reg.waiting;setUpdateStatus('新版本已下载，可以更新');}
    else if(reg.installing)setUpdateStatus('正在下载新版本…');
    else if(!swWaiting){
     const response=await fetch(`${import.meta.env.BASE_URL}version.json?check=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error('version unavailable');const latest=await response.json();if(typeof latest.version!=='string')throw Error('invalid version');
     const activeVersion=await new Promise(resolve=>{const channel=new MessageChannel();const timeout=setTimeout(()=>resolve(null),1500);channel.port1.onmessage=e=>{clearTimeout(timeout);channel.port1.close();resolve(e.data?.version);};reg.active?.postMessage({type:'GET_VERSION'},[channel.port2]);});
     if(activeVersion&&activeVersion!==__APP_VERSION__){reloadAvailable=true;setUpdateStatus('新版本已就绪，点击更新加载新页面');}
     else if(latest.version!==__APP_VERSION__){await navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js?release=${encodeURIComponent(latest.version)}`,{updateViaCache:'none'}).then(watchRegistration);setUpdateStatus('发现新版本，正在下载；完成后点击更新');}
     else setUpdateStatus('已检查，当前是最新版本');
    }
   })(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('timeout')),15000);})]);
  }catch{setUpdateStatus(swWaiting?'新版本已下载；联网检查未完成，仍可更新':'暂时无法检查更新，再点设置可重试');}
  finally{clearTimeout(timer);updateCheck=null;}
 })();return updateCheck;
}
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(updateRequested)location.reload();});
function fitKeyboard(){const v=window.visualViewport;if(!v)return;modalRoot.style.setProperty('--visible-height',`${v.height}px`);modalRoot.style.setProperty('--visible-top',`${v.offsetTop}px`);}
window.visualViewport?.addEventListener('resize',fitKeyboard);window.visualViewport?.addEventListener('scroll',fitKeyboard);fitKeyboard();
async function init(){try{state=await openStore();state=await updateState(s=>s);render();registerOffline();}catch(err){app.innerHTML=`<div class="fatal"><h1>暂时无法打开本地账本</h1><p>请确认 Safari 允许网站存储，并重新打开页面。不要清除网站数据，以免丢失已有账本。</p><p>${esc(err.message)}</p><button onclick="location.reload()">重新尝试</button></div>`;}}
init();
